(()=>{'use strict';const game=location.pathname.split('/').pop().replace('.html','');const form=document.getElementById('form'),input=document.getElementById('answer'),demo=document.getElementById('demo'),feedback=document.getElementById('feedback');let automated=false,watching=false,lastQuestion='',turn=0,rewardNo=0,session=crypto.randomUUID(),completed=false,selected=null,answerLock=false;const choices=document.createElement('div');choices.className='choices';choices.setAttribute('role','group');choices.setAttribute('aria-label','Choose the correct answer');form.querySelector('.equation').after(choices);let equipped=null;window.RaceSkins={draw(context,id,image,gold,_zero,sx,sy,sw,sh,dx,dy,dw,dh){context.save();if(!gold&&equipped?.color){const color=equipped.color;const hues={'#ef476f':330,'#ffd166':40,'#06d6a0':120,'#7c5cff':270,'#f3b6de':310};context.filter='hue-rotate('+(hues[color]??(Number(equipped.tier)*32))+'deg) saturate(1.25)';}context.drawImage(image,sx,sy,sw,sh,dx,dy,dw,dh);context.restore()},badge(){},wheels(){return false}};const playing=()=>state==='racing'||state==='running';const send=data=>{if(parent!==window)parent.postMessage(data,location.origin)};
const paceHud=game==='subway'?null:document.createElement('div');if(paceHud){paceHud.className='pace-gap';document.querySelector('.arena').append(paceHud);}window.RacePaceSnapshot=()=>{if(game==='subway')return{player:correct,opponent:null,gap:null,rate:null};const opponent=game==='jetski'?pace/TRACK*target:pace/LAP*FACTS;return{player:correct,opponent,gap:correct-opponent,rate:target}};function render(){const key=a+':'+b;if(key===lastQuestion)return;lastQuestion=key;const right=a*b,set=new Set([right]);for(const n of [right+a,right-b,right+b,right-a,right+1,right-1])if(n>=0&&set.size<4)set.add(n);while(set.size<4)set.add(right+set.size);const values=[...set];for(let i=values.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[values[i],values[j]]=[values[j],values[i]]}choices.replaceChildren(...values.map(n=>{const button=document.createElement('button');button.type='button';button.className='choice';button.textContent=n;button.dataset.value=n;button.onclick=()=>select(n,button);return button}));}
function select(n,button){if(!playing()||input.disabled||answerLock)return;answerLock=true;selected=n;button?.classList.add('selected');input.value=String(n);form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));setTimeout(()=>{answerLock=false;selected=null;render();choices.querySelectorAll('button').forEach(x=>x.classList.remove('selected'))},180)}
window.ArcadeRace={reward(){if(!automated&&!watching)send({type:'arcade-reward',amount:25,id:session+':'+(++rewardNo),game})},complete(){if(completed)return;completed=true;if(!automated&&!watching)send({type:'arcade-complete',game,correct,attempts,won:game==='subway'?true:won})}};
function begin(mode){send({type:'arcade-mode',mode});automated=mode!=='play';watching=mode==='video';completed=false;session=crypto.randomUUID();rewardNo=0;turn=0;lastQuestion='';document.body.classList.toggle('watch-mode',watching);document.body.classList.toggle('demo-active',automated);reset();start();render();demo.textContent=automated?'Stop demo':'Demo mode';document.getElementById('demoBadge').hidden=!automated;}
let lastAuto=0;function loop(now){render();const snap=window.RacePaceSnapshot();if(paceHud)paceHud.textContent=(Math.abs(snap.gap)<.25?'SIDE BY SIDE':snap.gap>0?'YOU LEAD +'+snap.gap.toFixed(1):'PACE LEADS +'+(-snap.gap).toFixed(1))+' FACTS';const enabled=playing()&&!input.disabled&&!answerLock;for(const button of choices.children)button.disabled=!enabled;if(automated&&enabled&&now-lastAuto>1300){lastAuto=now;turn++;const n=turn%5===0?a*b+a:a*b;select(n,[...choices.children].find(x=>+x.dataset.value===n));}if(automated&&(state==='results'||state==='ready')){automated=false;document.body.classList.remove('demo-active');demo.textContent='Demo mode';}demo.disabled=!ready;requestAnimationFrame(loop)}requestAnimationFrame(loop);demo.addEventListener('click',()=>{if(automated){automated=watching=false;send({type:'arcade-mode',mode:'play'});document.body.classList.remove('demo-active','watch-mode');reset();demo.textContent='Demo mode'}else begin('demo')});document.getElementById('reset').addEventListener('click',()=>{automated=watching=false;completed=false;send({type:'arcade-mode',mode:'play'});document.body.classList.remove('demo-active','watch-mode')});document.getElementById('again').addEventListener('click',()=>{automated=watching=false;completed=false;send({type:'arcade-mode',mode:'play'});session=crypto.randomUUID();document.body.classList.remove('demo-active','watch-mode')});window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent)return;if(e.data?.type==='arcade-gear'){equipped=e.data.gear||e.data;window.arcadeGear=equipped;return}if(e.data?.type!=='arcade-command')return;const data=e.data;if(data.gear){equipped=data.gear;const label=document.getElementById('gearLabel')||Object.assign(document.createElement('span'),{id:'gearLabel',className:'store-gear'});label.textContent='Equipped: '+(data.gear.name||data.gear.id||data.gear);document.querySelector('.tools').append(label);window.arcadeGear=data.gear;}const requested=data.action||'play';function launch(){if(ready)begin(requested);else setTimeout(launch,100)}launch()});send({type:'arcade-ready',game});feedback.textContent='Choose the right answer. Correct answers earn 25 coins!';
})();
